{#
  =============================================================================
  TEMPLATE-PART: Club-Logo (nur in anderen Views per include nutzen)
  - CSS: match-team-logo  |  alt: Medien-Alt oder "Vereinslogo: {Name}"
  =============================================================================
#}
{% set thumb = null %}
{% if team_post is defined and team_post.thumbnail is defined %}
  {% if team_post.thumbnail.medium_large is defined and team_post.thumbnail.medium_large.url %}
    {% set thumb = team_post.thumbnail.medium_large %}
  {% elseif team_post.thumbnail.medium is defined and team_post.thumbnail.medium.url %}
    {% set thumb = team_post.thumbnail.medium %}
  {% endif %}
{% endif %}
{% if thumb and thumb.url %}
  {% set logo_alt = (thumb.alt is defined and thumb.alt) ? thumb.alt : ('Vereinslogo: ' ~ (team_post.title|default(''))) %}
<img class="match-team-logo{{ logo_extra_class is defined and logo_extra_class ? ' ' ~ logo_extra_class : '' }}" src="{{ thumb.url }}" alt="{{ logo_alt|e('html') }}"{% if logo_max_width is defined and logo_max_width %} width="{{ logo_max_width }}"{% endif %}{% if logo_max_height is defined and logo_max_height %} height="{{ logo_max_height }}"{% endif %} loading="{{ logo_loading|default('lazy') }}" decoding="{{ logo_decoding|default('async') }}"{% if logo_fetchpriority is defined and logo_fetchpriority %} fetchpriority="{{ logo_fetchpriority }}"{% endif %}>
{% endif %}
